<code>
sub prase_results {
    my ($file_path,$aref) = @_;
    open(my $fh, '<', "$file_path") or return 0;
    while (my $line = <$fh>) {
        chomp($line);
        my ($key,$group,$value,$version,$file,$count) = split(/,/,$line);
	my $key = 1;
	foreach my $k (@{$aref}) {
	    if ($k->{"group"} eq $group) {
		$k->{"version"} = [ sort uniq $version, @{$k->{"version"}} ];
		$key = 0;
	    }
	}
        push @{ $aref }, {
            group => $group,
            versions => [ $version ]
        } if ($key);
    }
    close ($fh);
    return 1;
}
